package com.example.demo.adapters.jdbc;

import com.example.demo.domain.Person;
import com.example.demo.repository.PersonRepository;
import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public final class JdbcPersonRepository implements PersonRepository {

    private final JdbcClient jdbc;

    public JdbcPersonRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Optional<Person> findById(UUID id) {
        return jdbc.sql("select id, email, created_at from people where id = :id")
                .param("id", id)
                .query(Person.class)
                .optional();
    }

    @Override
    public List<Person> findAll() {
        return jdbc.sql("select id, email, created_at from people order by id")
                .query(Person.class)
                .list();
    }

    @Override
    public Person save(Person value) {
        return jdbc.sql("insert into people (id, email, created_at) values (:id, :email, :created_at) on conflict (id) do update set email = excluded.email, created_at = excluded.created_at returning id, email, created_at")
                .param("id", value.id())
                .param("email", value.email())
                .param("created_at", Timestamp.from(value.createdAt()))
                .query(Person.class)
                .single();
    }

    @Override
    public boolean deleteById(UUID id) {
        return jdbc.sql("delete from people where id = :id")
                .param("id", id)
                .update() > 0;
    }
}
